import{_ as t,o as e,c as o,a2 as n}from"./chunks/framework.gku7e_5h.js";const u=JSON.parse('{"title":"Getting connected 🌍🛰️","description":"","frontmatter":{"title":"Getting connected 🌍🛰️","prev":{"text":"Guides","link":"../"},"next":{"link":"./installing-dependencies"}},"headers":[],"relativePath":"guides/koha-dev/getting-connected.md","filePath":"guides/koha-dev/getting-connected.md","lastUpdated":1785344570000}'),i={name:"guides/koha-dev/getting-connected.md"};function r(h,a,s,c,f,d){return e(),o("div",null,[...a[0]||(a[0]=[n(`<h2 id="get-on-bugzilla" tabindex="-1" data-v-86c3ff24>Get on Bugzilla <a class="header-anchor" href="#get-on-bugzilla" aria-label="Permalink to &quot;Get on Bugzilla&quot;" data-v-86c3ff24>​</a></h2><p data-v-86c3ff24>Open an account on <a href="http://bugs.koha-community.org/" target="_blank" rel="noreferrer" data-v-86c3ff24>Bugzilla</a> .</p><p data-v-86c3ff24>You will need this account to:</p><ul data-v-86c3ff24><li data-v-86c3ff24>🐛 Report bugs</li><li data-v-86c3ff24>🧠 Make suggestions for enhancements and new features</li><li data-v-86c3ff24>🧪 Test and sign off on patches</li><li data-v-86c3ff24>📨 Submit patches</li></ul><pre class="mermaid" data-v-86c3ff24>flowchart TD
  A[Notice something about Koha] --&gt; B[Search Bugzilla: has it been reported?]
  B --&gt; |Yes| C[Add a comment
  Add yourself to CC
  Vote, sponsor, promote]
  B --&gt; |No| D[Document steps to reproduce]
  D --&gt; E[File a bug report]
  D --&gt; F[Ask the community about it]
  E --&gt; G[Ask the community about it]
</pre><h2 id="check-the-koha-manual" tabindex="-1" data-v-86c3ff24>Check the Koha Manual <a class="header-anchor" href="#check-the-koha-manual" aria-label="Permalink to &quot;Check the Koha Manual&quot;" data-v-86c3ff24>​</a></h2><p data-v-86c3ff24>You&#39;ve probably been to the <a href="https://koha-community.org/manual/latest/en/html/" target="_blank" rel="noreferrer" data-v-86c3ff24>Koha Manual</a> before. Don&#39;t be afraid to <a href="https://wiki.koha-community.org/wiki/Editing_the_Koha_Manual" target="_blank" rel="noreferrer" data-v-86c3ff24>contribute</a> when and where you can.</p><h2 id="check-the-koha-wiki" tabindex="-1" data-v-86c3ff24>Check the Koha Wiki <a class="header-anchor" href="#check-the-koha-wiki" aria-label="Permalink to &quot;Check the Koha Wiki&quot;" data-v-86c3ff24>​</a></h2><p data-v-86c3ff24>Familiarize yourself with <a href="https://wiki.koha-community.org/wiki/Bug_Reporting_Guidelines" target="_blank" rel="noreferrer" data-v-86c3ff24>how to write a good bug report</a> and learn the <a href="https://wiki.koha-community.org/wiki/Development_workflow" target="_blank" rel="noreferrer" data-v-86c3ff24>development workflow</a>. Lurk around Bugzilla for a while to see how the process works. ⛺</p><pre class="mermaid" data-v-86c3ff24>flowchart TD
  A[Write a patch] --&gt; B[write a test plan]
  B --&gt; |Attach to bug| C[Needs Sign off]
  C --&gt;|Passes tests| D[Signed off]
  C --&gt;|Fails community tests| E[Failed QA]
  C --&gt;|Needs a rebase| F[Patch does not apply]
  E &amp; F --&gt;A
  D --&gt;G[QA testing]
  G --&gt;|Passes tests| H[Passed QA]
  G --&gt;|Fails QA tests| E
  H --&gt; I[Release manager&#39;s inspection]
  I --&gt;|Fails RM inspection| E
  I --&gt;|Passes inspection| J[Pushed to Main for next release]
</pre><h2 id="check-the-koha-dashboard" tabindex="-1" data-v-86c3ff24>Check the Koha Dashboard <a class="header-anchor" href="#check-the-koha-dashboard" aria-label="Permalink to &quot;Check the Koha Dashboard&quot;" data-v-86c3ff24>​</a></h2><p data-v-86c3ff24>See what&#39;s new, what&#39;s ready to test and the latest progress in the community. The <a href="https://dashboard.koha-community.org/" target="_blank" rel="noreferrer" data-v-86c3ff24> Dashboard</a> is a great place to find inspiration or just to stay up to date.</p><h2 id="hook-up-with-the-koha-community" tabindex="-1" data-v-86c3ff24>Hook up with the Koha Community <a class="header-anchor" href="#hook-up-with-the-koha-community" aria-label="Permalink to &quot;Hook up with the Koha Community&quot;" data-v-86c3ff24>​</a></h2><ul data-v-86c3ff24><li data-v-86c3ff24>🌊 Lost in a sea of browser tabs?</li><li data-v-86c3ff24>🐛 Bug driving you crazy?</li><li data-v-86c3ff24>🤖 Tempted to consult with an AI chat bot?</li></ul><p data-v-86c3ff24>Sometimes it&#39;s best to ask a smart group of humans if they can answer your question or help point you in the right direction. 🧭</p><p data-v-86c3ff24>The new <a href="https://chat.koha-community.org/" target="_blank" rel="noreferrer" data-v-86c3ff24>Koha Community Chat</a> on Mattermost is an awesome place to get in touch with experts in real time. It&#39;s like Slack, but open source and hosted by the community.</p><p data-v-86c3ff24>Can&#39;t get enough email in your life? Join the <a href="https://wiki.koha-community.org/wiki/Mailing_lists" target="_blank" rel="noreferrer" data-v-86c3ff24>mailing lists</a> too. 📨</p><h2 id="make-friends" tabindex="-1" data-v-86c3ff24>Make friends <a class="header-anchor" href="#make-friends" aria-label="Permalink to &quot;Make friends&quot;" data-v-86c3ff24>​</a></h2><img src="https://imgs.xkcd.com/comics/bug_thread.png" data-v-86c3ff24><p data-v-86c3ff24><a href="https://xkcd.com/2881/" target="_blank" rel="noreferrer" data-v-86c3ff24>Obligitory xkcd</a></p>`,20)])])}const g=t(i,[["render",r],["__scopeId","data-v-86c3ff24"]]);export{u as __pageData,g as default};
